CREATE TABLE student(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,birth_date DATE NOT NULL,ssn VARCHAR(9) NOT NULL,status VARCHAR(16) NOT NULL,graduation_date DATE NULL,deleted_at DATETIME(3) NULL,version BIGINT NOT NULL DEFAULT 0, CHECK(status IN ('ENROLLED','GRADUATED','SUSPENDED')));
CREATE TABLE professor(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,birth_date DATE NOT NULL,ssn VARCHAR(9) NOT NULL,status VARCHAR(16) NOT NULL,department VARCHAR(100) NOT NULL,deleted_at DATETIME(3) NULL,version BIGINT NOT NULL DEFAULT 0,CHECK(status IN ('ON_DUTY','ON_LEAVE','RETIRED')));
CREATE TABLE user_account(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(64) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',must_change_password BOOLEAN NOT NULL DEFAULT TRUE,credential_version BIGINT NOT NULL DEFAULT 0,student_id BIGINT NULL UNIQUE,professor_id BIGINT NULL UNIQUE,FOREIGN KEY(student_id) REFERENCES student(id),FOREIGN KEY(professor_id) REFERENCES professor(id),CHECK(role IN ('STUDENT','PROFESSOR','REGISTRAR')),CHECK(status IN ('ACTIVE','DISABLED')),CHECK((role='STUDENT' AND student_id IS NOT NULL AND professor_id IS NULL) OR (role='PROFESSOR' AND professor_id IS NOT NULL AND student_id IS NULL) OR (role='REGISTRAR' AND student_id IS NULL AND professor_id IS NULL)));
CREATE TABLE semester(id BIGINT PRIMARY KEY,name VARCHAR(64) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,registration_open_at DATETIME(3) NOT NULL,registration_close_at DATETIME(3) NOT NULL,add_drop_start_at DATETIME(3) NOT NULL,add_drop_end_at DATETIME(3) NOT NULL,state VARCHAR(16) NOT NULL,teaching_state VARCHAR(16) NOT NULL,CHECK(state IN ('OPEN','CLOSING','CLOSED')),CHECK(teaching_state IN ('UPCOMING','IN_PROGRESS','COMPLETED')),CHECK(start_date<=end_date AND registration_open_at<registration_close_at AND add_drop_start_at<add_drop_end_at));
CREATE TABLE academic_context(id TINYINT PRIMARY KEY,registration_semester_id BIGINT NOT NULL,previous_completed_semester_id BIGINT NULL,version BIGINT NOT NULL DEFAULT 0,CHECK(id=1),FOREIGN KEY(registration_semester_id) REFERENCES semester(id),FOREIGN KEY(previous_completed_semester_id) REFERENCES semester(id));
CREATE TABLE catalog_snapshot(id BIGINT PRIMARY KEY,semester_id BIGINT NOT NULL,source_version VARCHAR(128) NOT NULL,fetched_at DATETIME(3) NOT NULL,status VARCHAR(16) NOT NULL,UNIQUE(semester_id,source_version),FOREIGN KEY(semester_id) REFERENCES semester(id));
CREATE TABLE course(id BIGINT PRIMARY KEY,external_id VARCHAR(64) NOT NULL UNIQUE);
CREATE TABLE course_snapshot(snapshot_id BIGINT NOT NULL,course_id BIGINT NOT NULL,name VARCHAR(150) NOT NULL,department VARCHAR(100) NOT NULL,PRIMARY KEY(snapshot_id,course_id),FOREIGN KEY(snapshot_id) REFERENCES catalog_snapshot(id),FOREIGN KEY(course_id) REFERENCES course(id));
CREATE TABLE course_prerequisite(snapshot_id BIGINT NOT NULL,course_id BIGINT NOT NULL,prerequisite_course_id BIGINT NOT NULL,PRIMARY KEY(snapshot_id,course_id,prerequisite_course_id),FOREIGN KEY(snapshot_id,course_id) REFERENCES course_snapshot(snapshot_id,course_id),FOREIGN KEY(prerequisite_course_id) REFERENCES course(id),CHECK(course_id<>prerequisite_course_id));
CREATE TABLE offering(id BIGINT PRIMARY KEY,external_id VARCHAR(64) NOT NULL,course_id BIGINT NOT NULL,semester_id BIGINT NOT NULL,snapshot_id BIGINT NOT NULL,catalog_status VARCHAR(16) NOT NULL DEFAULT 'OPEN',UNIQUE(semester_id,external_id),INDEX(semester_id,course_id),FOREIGN KEY(course_id) REFERENCES course(id),FOREIGN KEY(semester_id) REFERENCES semester(id),FOREIGN KEY(snapshot_id,course_id) REFERENCES course_snapshot(snapshot_id,course_id));
CREATE TABLE offering_runtime(offering_id BIGINT PRIMARY KEY,semester_id BIGINT NOT NULL,state VARCHAR(16) NOT NULL DEFAULT 'OPEN',capacity SMALLINT NOT NULL DEFAULT 10,enrolled_count SMALLINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,fee DECIMAL(12,2) NOT NULL DEFAULT 1000.00,INDEX(semester_id,state),FOREIGN KEY(offering_id) REFERENCES offering(id),FOREIGN KEY(semester_id) REFERENCES semester(id),CHECK(capacity=10 AND enrolled_count BETWEEN 0 AND capacity),CHECK(state IN ('OPEN','CONFIRMED','CANCELLED')),CHECK(fee>=0));
CREATE TABLE offering_assignment(offering_id BIGINT PRIMARY KEY,professor_id BIGINT NOT NULL,assigned_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),version BIGINT NOT NULL DEFAULT 0,INDEX(professor_id,offering_id),FOREIGN KEY(offering_id) REFERENCES offering(id),FOREIGN KEY(professor_id) REFERENCES professor(id));
CREATE TABLE offering_meeting(id BIGINT PRIMARY KEY AUTO_INCREMENT,offering_id BIGINT NOT NULL,weekday TINYINT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,first_date DATE NOT NULL,last_date DATE NOT NULL,week_mask VARCHAR(128) NULL,INDEX(offering_id),FOREIGN KEY(offering_id) REFERENCES offering(id),CHECK(weekday BETWEEN 1 AND 7),CHECK(start_time<end_time),CHECK(first_date<=last_date));
CREATE TABLE teaching_eligibility(professor_id BIGINT NOT NULL,course_id BIGINT NOT NULL,PRIMARY KEY(professor_id,course_id),FOREIGN KEY(professor_id) REFERENCES professor(id),FOREIGN KEY(course_id) REFERENCES course(id));
CREATE TABLE teaching_guard(professor_id BIGINT NOT NULL,semester_id BIGINT NOT NULL,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(professor_id,semester_id),FOREIGN KEY(professor_id) REFERENCES professor(id),FOREIGN KEY(semester_id) REFERENCES semester(id));
CREATE TABLE schedule(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id BIGINT NOT NULL,semester_id BIGINT NOT NULL,state VARCHAR(16) NOT NULL DEFAULT 'DRAFT',version BIGINT NOT NULL DEFAULT 0,submitted_choices_json JSON NULL,first_submitted_at DATETIME(3) NULL,last_submitted_at DATETIME(3) NULL,UNIQUE(student_id,semester_id),FOREIGN KEY(student_id) REFERENCES student(id),FOREIGN KEY(semester_id) REFERENCES semester(id),CHECK(state IN ('DRAFT','SUBMITTED','FINALIZED','DELETED')));
CREATE TABLE schedule_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,schedule_id BIGINT NOT NULL,offering_id BIGINT NOT NULL,choice_type VARCHAR(16) NOT NULL,choice_order TINYINT NOT NULL,state VARCHAR(16) NOT NULL DEFAULT 'SELECTED',cancel_reason VARCHAR(32) NULL,UNIQUE(schedule_id,offering_id),UNIQUE(schedule_id,choice_type,choice_order),FOREIGN KEY(schedule_id) REFERENCES schedule(id),FOREIGN KEY(offering_id) REFERENCES offering(id),CHECK((choice_type='PRIMARY' AND choice_order BETWEEN 1 AND 4) OR (choice_type='ALTERNATE' AND choice_order BETWEEN 1 AND 2)));
CREATE TABLE enrollment(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id BIGINT NOT NULL,offering_id BIGINT NOT NULL,state VARCHAR(16) NOT NULL,origin_type VARCHAR(16) NOT NULL,enrolled_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),version BIGINT NOT NULL DEFAULT 0,cancel_reason VARCHAR(32) NULL,UNIQUE(student_id,offering_id),INDEX(offering_id,state),FOREIGN KEY(student_id) REFERENCES student(id),FOREIGN KEY(offering_id) REFERENCES offering(id),CHECK(state IN ('ACTIVE','WITHDRAWN','CANCELLED')),CHECK(origin_type IN ('PRIMARY','ALTERNATE')));
CREATE TABLE grade(enrollment_id BIGINT PRIMARY KEY,grade VARCHAR(1) NULL,version BIGINT NOT NULL DEFAULT 0,entered_by BIGINT NULL,updated_at DATETIME(3) NULL,FOREIGN KEY(enrollment_id) REFERENCES enrollment(id),FOREIGN KEY(entered_by) REFERENCES professor(id),CHECK(grade IS NULL OR grade IN ('A','B','C','D','F','I')));
CREATE TABLE close_job(id BIGINT PRIMARY KEY AUTO_INCREMENT,semester_id BIGINT NOT NULL UNIQUE,state VARCHAR(24) NOT NULL DEFAULT 'REQUESTED',attempt_count INT NOT NULL DEFAULT 0,lease_token BIGINT NOT NULL DEFAULT 0,lease_owner VARCHAR(64) NULL,lease_until DATETIME(3) NULL,requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),last_error VARCHAR(500) NULL,summary_json JSON NULL,FOREIGN KEY(semester_id) REFERENCES semester(id));
CREATE TABLE billing_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,semester_id BIGINT NOT NULL,student_id BIGINT NOT NULL,close_job_id BIGINT NOT NULL,business_key VARCHAR(128) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CNY',snapshot_json JSON NOT NULL,payload_hash CHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(semester_id,student_id),FOREIGN KEY(semester_id) REFERENCES semester(id),FOREIGN KEY(student_id) REFERENCES student(id),FOREIGN KEY(close_job_id) REFERENCES close_job(id));
CREATE TABLE billing_outbox(id BIGINT PRIMARY KEY AUTO_INCREMENT,billing_record_id BIGINT NOT NULL UNIQUE,state VARCHAR(16) NOT NULL DEFAULT 'PENDING',attempt_count INT NOT NULL DEFAULT 0,next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),lease_token BIGINT NOT NULL DEFAULT 0,lease_owner VARCHAR(64) NULL,lease_until DATETIME(3) NULL,external_ref VARCHAR(128) NULL,last_error VARCHAR(500) NULL,INDEX(state,next_attempt_at),FOREIGN KEY(billing_record_id) REFERENCES billing_record(id),CHECK(state IN ('PENDING','SENDING','RETRYING','SENT')));
CREATE TABLE request_dedup(actor_id BIGINT NOT NULL,operation VARCHAR(100) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,response_json JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(actor_id,operation,idempotency_key),FOREIGN KEY(actor_id) REFERENCES user_account(id));
CREATE TABLE audit_event(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT NULL,event_type VARCHAR(64) NOT NULL,entity_id VARCHAR(128) NULL,detail TEXT NULL,trace_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX(event_type,created_at));
